import { IProduct } from '@apps/Products/@types/products.types';
import { showModal } from '@ui-kit/Modal/modalsHelper';

import ProductAddModal from '.';

export const addProductInModalAsync = (title = 'Добавление продукта'): Promise<IProduct> => {
  return new Promise<IProduct>((res, rej) => {
    showModal({
      onClose: rej,
      title,
      children: (close: () => void) => (
        <ProductAddModal
          onSave={(v) => {
            res(v);
            close();
          }}
        />
      ),
    });
  });
};

export const editProductInModalAsync = (
  product: IProduct,
  title = 'Редактирование продукта',
): Promise<IProduct> => {
  return new Promise<IProduct>((res, rej) => {
    showModal({
      onClose: rej,
      title,
      size: 'sm',
      children: (close: () => void) => (
        <ProductAddModal
          data={product}
          onSave={(v) => {
            res(v);
            close();
          }}
        />
      ),
    });
  });
};
